 const cropPointerDown=(e:ReactPointerEvent<HTMLElement>,mode:"create"|"move"|"resize"="create",handle?:string)=>{if(!selected)return;e.stopPropagation();const r=e.currentTarget.closest(".ps-crop-overlay")?.getBoundingClientRect();if(!r)return;const px=Math.max(0,Math.min(100,(e.clientX-r.left)/scale/selected.width*100)),py=Math.max(0,Math.min(100,(e.clientY-r.top)/scale/selected.height*100)),initial=cropDraft??{x:px,y:py,w:1,h:1};cropStartRef.current={mode,startX:px,startY:py,initial,handle};e.currentTarget.setPointerCapture(e.pointerId);if(mode==="create")setCropDraft({x:px,y:py,w:1,h:1});};
 const cropPointerMove=(e:ReactPointerEvent<HTMLDivElement>)=>{const d=cropStartRef.current;if(!d||!selected)return;const r=e.currentTarget.getBoundingClientRect(),px=Math.max(0,Math.min(100,(e.clientX-r.left)/scale/selected.width*100)),py=Math.max(0,Math.min(100,(e.clientY-r.top)/scale/selected.height*100));if(d.mode==="create"){let w=Math.max(1,Math.abs(px-d.startX)),h=Math.max(1,Math.abs(py-d.startY));const ratios:Record<string,number>={"1:1":1,"3:4":.75,"4:5":.8,"35:45":35/45,"2:3":2/3};const ratio=ratios[cropAspect];if(ratio){const wantedH=w*selected.width/(ratio*selected.height);if(wantedH<=100)h=wantedH;else w=h*ratio*selected.height/selected.width;}const x=Math.min(d.startX,px),y=Math.min(d.startY,py);setCropDraft({x,y,w:Math.max(1,Math.min(100-x,w)),h:Math.max(1,Math.min(100-y,h))});return;}if(d.mode==="move"){const w=d.initial.w,h=d.initial.h;setCropDraft({x:Math.max(0,Math.min(100-w,d.initial.x+px-d.startX)),y:Math.max(0,Math.min(100-h,d.initial.y+py-d.startY)),w,h});return;}const right=d.handle?.includes("e"),bottom=d.handle?.includes("s"),x=right?d.initial.x:d.initial.x+(px-d.startX),y=bottom?d.initial.y:d.initial.y+(py-d.startY),x2=right?d.initial.x+d.initial.w+(px-d.startX):d.initial.x+d.initial.w,y2=bottom?d.initial.y+d.initial.h+(py-d.startY):d.initial.y+d.initial.h,nx=Math.max(0,Math.min(99,x)),ny=Math.max(0,Math.min(99,y));setCropDraft({x:nx,y:ny,w:Math.max(1,Math.min(100-nx,x2-nx)),h:Math.max(1,Math.min(100-ny,y2-ny))});};
 const cropPointerUp=()=>{cropStartRef.current=null;};
 const applyCrop=()=>{if(!selected||!cropDraft)return;const x=Math.max(0,Math.min(99,cropDraft.x)),y=Math.max(0,Math.min(99,cropDraft.y)),w=Math.max(1,Math.min(100-x,cropDraft.w)),h=Math.max(1,Math.min(100-y,cropDraft.h));const prior=selected.crop??{x:0,y:0,w:100,h:100};const c={x:prior.x+prior.w*x/100,y:prior.y+prior.h*y/100,w:prior.w*w/100,h:prior.h*h/100};patchLayer(selected.id,{crop:c,x:selected.x+selected.width*x/100,y:selected.y+selected.height*y/100,width:selected.width*w/100,height:selected.height*h/100});setCropDraft(null);setTool("select");};

