 const pngWithDpi=(canvas:HTMLCanvasElement,dpi:number)=>{const raw=atob(canvas.toDataURL("image/png").split(",")[1]),src=Uint8Array.from(raw,ch=>ch.charCodeAt(0)),read32=(a:number)=>((src[a]<<24)|(src[a+1]<<16)|(src[a+2]<<8)|src[a+3])>>>0,crc=(data:Uint8Array)=>{let v=0xffffffff;for(const b of data){v^=b;for(let k=0;k<8;k++)v=(v>>>1)^((v&1)?0xedb88320:0);}return(v^0xffffffff)>>>0;};let pos=8;while(pos<src.length){const len=read32(pos),type=String.fromCharCode(...src.slice(pos+4,pos+8));if(type==="IHDR"){const ppm=Math.round(dpi/0.0254),chunk=new Uint8Array(21);chunk.set([0,0,0,9,112,72,89,115],0);chunk[8]=(ppm>>>24)&255;chunk[9]=(ppm>>>16)&255;chunk[10]=(ppm>>>8)&255;chunk[11]=ppm&255;chunk[12]=(ppm>>>24)&255;chunk[13]=(ppm>>>16)&255;chunk[14]=(ppm>>>8)&255;chunk[15]=ppm&255;chunk[16]=1;const sum=crc(chunk.slice(4,17));chunk[17]=sum>>>24;chunk[18]=sum>>>16;chunk[19]=sum>>>8;chunk[20]=sum&255;const merged=new Uint8Array(src.length+chunk.length),insertAt=pos+12+len;merged.set(src.slice(0,insertAt));merged.set(chunk,insertAt);merged.set(src.slice(insertAt),insertAt+chunk.length);return "data:image/png;base64,"+btoa(Array.from(merged,x=>String.fromCharCode(x)).join(""));}pos+=12+len;}return canvas.toDataURL("image/png");};
 const renderPrintCanvas=async()=>{const paper=printPaperSizes[printPaper]??printPaperSizes["Current page"];let pw=paper.w,ph=paper.h;if(printOrientation==="Landscape"&&ph>pw)[pw,ph]=[ph,pw];if(printOrientation==="Portrait"&&pw>ph)[pw,ph]=[ph,pw];const out=document.createElement("canvas");out.width=Math.round(pw*printDpi);out.height=Math.round(ph*printDpi);const ctx=out.getContext("2d");if(!ctx)return null;ctx.fillStyle="#fff";ctx.fillRect(0,0,out.width,out.height);const margin=Math.max(0,printMargin)*printDpi/25.4,availW=Math.max(1,out.width-margin*2),availH=Math.max(1,out.height-margin*2),fit=Math.min(availW/page.width,availH/page.height),dw=page.width*fit,dh=page.height*fit,ox=(out.width-dw)/2,oy=(out.height-dh)/2;ctx.save();ctx.translate(ox,oy);ctx.scale(fit,fit);for(const l of page.layers){if(!l.visible)continue;ctx.save();ctx.globalAlpha=l.opacity/100;ctx.translate(l.x+l.width/2,l.y+l.height/2);ctx.rotate(l.rotation*Math.PI/180);if(l.kind==="image"&&l.src){if(l.backgroundColor){ctx.fillStyle=l.backgroundColor;ctx.fillRect(-l.width/2,-l.height/2,l.width,l.height);}ctx.filter=`brightness(${l.brightness??100}%) contrast(${l.contrast??100}%) saturate(${l.saturation??100}%)`;const img=new Image();img.src=l.src;await new Promise<void>(r=>{img.onload=()=>r();img.onerror=()=>r();});if(img.naturalWidth){const cr=l.crop??{x:0,y:0,w:100,h:100};ctx.drawImage(img,img.naturalWidth*cr.x/100,img.naturalHeight*cr.y/100,img.naturalWidth*cr.w/100,img.naturalHeight*cr.h/100,-l.width/2,-l.height/2,l.width,l.height);if(l.borderEnabled){ctx.filter="none";ctx.strokeStyle=l.borderColor??"#000000";ctx.lineWidth=(l.borderMm??.5)*300/25.4;ctx.strokeRect(-l.width/2,-l.height/2,l.width,l.height);}}}else{ctx.fillStyle="#202b39";ctx.font="bold 42px Segoe UI";ctx.textBaseline="middle";ctx.fillText(l.text??"",-l.width/2,0,l.width);}ctx.restore();}ctx.restore();return out;};
