 const exportPage=async(format:"PNG"|"JPG"="PNG",quality=0.9,target=0)=>{const c=document.createElement("canvas");c.width=page.width;c.height=page.height;const ctx=c.getContext("2d");if(!ctx)return;ctx.fillStyle="#fff";ctx.fillRect(0,0,c.width,c.height);for(const l of page.layers){if(!l.visible)continue;ctx.save();ctx.globalAlpha=l.opacity/100;ctx.translate(l.x+l.width/2,l.y+l.height/2);ctx.rotate(l.rotation*Math.PI/180);if(l.kind==="image"&&l.src){ctx.fillStyle=l.backgroundColor??"transparent";if(l.backgroundColor)ctx.fillRect(-l.width/2,-l.height/2,l.width,l.height);ctx.filter=`brightness(${l.brightness??100}%) contrast(${l.contrast??100}%) saturate(${l.saturation??100}%)`;const img=new Image();img.src=l.src;await new Promise<void>(r=>{img.onload=()=>r();img.onerror=()=>r();});if(img.naturalWidth){const cr=l.crop??{x:0,y:0,w:100,h:100};ctx.drawImage(img,img.naturalWidth*cr.x/100,img.naturalHeight*cr.y/100,img.naturalWidth*cr.w/100,img.naturalHeight*cr.h/100,-l.width/2,-l.height/2,l.width,l.height);if(l.borderEnabled){ctx.filter="none";ctx.strokeStyle=l.borderColor??"#000000";ctx.lineWidth=(l.borderMm??.5)*300/25.4;ctx.strokeRect(-l.width/2,-l.height/2,l.width,l.height);}}}else{ctx.fillStyle="#202b39";ctx.font="bold 42px Segoe UI";ctx.textBaseline="middle";ctx.fillText(l.text??"",-l.width/2,0,l.width);}ctx.restore();}const a=document.createElement("a");if(format==="JPG"){let q=quality,blob=await new Promise<Blob|null>(resolve=>c.toBlob(resolve,"image/jpeg",q));while(blob&&target>0&&blob.size>target*1024&&q>.16){q=Math.max(.16,q-.07);blob=await new Promise<Blob|null>(resolve=>c.toBlob(resolve,"image/jpeg",q));}if(!blob)return;if(target>0&&blob.size>target*1024)alert(`Requested ${target} KB target could not be reached without reducing the image dimensions. Saved ${Math.ceil(blob.size/1024)} KB instead.`);a.href=URL.createObjectURL(blob);a.download=`tanshu-online-auto-photo-${page.id}.jpg`;}else{a.href=pngWithDpi(c,300);a.download=`tanshu-online-auto-photo-${page.id}.png`;}a.click();if(format==="JPG")window.setTimeout(()=>URL.revokeObjectURL(a.href),1500);};
